<script setup>
import { computed,nextTick,onMounted,onBeforeUnmount,ref } from 'vue'
import {isStaticDemo} from '../runtime.js'
import UiIcon from './UiIcon.vue'
import { db } from '../domain/store.js'
import { account,savePreferences,signOut } from '../domain/account.js'
import { globalSearch } from '../domain/globalSearch.js'
import { notifications,readKeys,unreadNotifications,refreshReadState,markRead,noticeError,noticeBusy } from '../domain/notifications.js'
const emit=defineEmits(['target','account','runtime','message'])
const panel=ref(''),query=ref(''),searchInput=ref(null),activeResult=ref(-1),noticeFilter=ref('all'),noticeLimit=ref(20),saving=ref(false),full=ref(!!document.fullscreenElement)
const searchResults=computed(()=>globalSearch(db,query.value)),kinds={menu:'菜单',station:'站点',device:'设备',socket:'插座',order:'订单',report:'报修'}
const visibleNotices=computed(()=>(noticeFilter.value==='unread'?unreadNotifications.value:notifications.value).slice(0,noticeLimit.value))
const noticeTotal=computed(()=>(noticeFilter.value==='unread'?unreadNotifications.value:notifications.value).length)
const avatar=computed(()=>Array.from(account.user?.displayName||'管')[0]),fullSupported=!!document.fullscreenEnabled&&typeof document.documentElement.requestFullscreen==='function'
async function toggle(name){panel.value=panel.value===name?'':name;activeResult.value=-1;if(panel.value==='search'){await nextTick();searchInput.value?.focus()}if(panel.value==='notifications'){noticeLimit.value=20;refreshReadState()}}
function close(){panel.value=''}
function selectResult(result){close();emit('target',result.target)}
function moveResult(offset){const n=searchResults.value.length;if(n)activeResult.value=(activeResult.value+offset+n)%n}
function enterResult(){const item=searchResults.value[Math.max(activeResult.value,0)];if(item)selectResult(item)}
async function chooseFont(value){saving.value=true;try{await savePreferences({...account.user.preferences,fontSize:value});close();emit('message','全局字号已保存。')}catch(e){emit('message',e.message,true)}finally{saving.value=false}}
function accountAction(mode){close();emit('account',mode)}
async function logout(){saving.value=true;try{await signOut();close()}catch(e){emit('message',e.message,true)}finally{saving.value=false}}
async function readNotice(item){try{if(!readKeys.value.has(item.key))await markRead([item.key]);close();emit('target',item.target)}catch(e){emit('message',e.message,true)}}
async function readAll(){try{await markRead(unreadNotifications.value.map(n=>n.key));emit('message','全部通知已标为已读。')}catch(e){emit('message',e.message,true)}}
async function toggleFull(){if(!fullSupported)return emit('message','当前浏览器不支持网页全屏，可使用浏览器自带全屏功能。',true);try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{emit('message','浏览器限制了网页全屏，可使用浏览器自带全屏功能。',true)}}
function fullscreenChanged(){full.value=!!document.fullscreenElement}
function clickOutside(e){if(e.target instanceof Element&&!e.target.closest('[data-topbar-popup]'))close()}
function keys(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();toggle('search')}if(e.key==='Escape')close()}
function displayTime(value){const date=new Date(/^\d{4}-\d\d-\d\d /.test(value)?value.replace(' ','T')+'+08:00':value);return Number.isNaN(+date)?value:date.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
onMounted(()=>{document.addEventListener('click',clickOutside);document.addEventListener('keydown',keys);document.addEventListener('fullscreenchange',fullscreenChanged)})
onBeforeUnmount(()=>{document.removeEventListener('click',clickOutside);document.removeEventListener('keydown',keys);document.removeEventListener('fullscreenchange',fullscreenChanged)})
</script>
<template><div class="topbar-tools" data-topbar-popup>
 <button class="preview-mode-chip" @click="emit('runtime')" title="查看账号服务与业务运行状态">{{isStaticDemo?'公开演示':'本地模拟'}}<span v-if="!isStaticDemo" class="service-dot" :class="{offline:!account.serverOnline}"></span></button>
 <div class="utility-icons"><button class="icon-button" aria-label="全局搜索" title="全局搜索 Ctrl+K" :aria-expanded="panel==='search'" @click="toggle('search')"><UiIcon name="search" size="1.45rem"/></button><button class="icon-button notification-button" aria-label="通知中心" :aria-expanded="panel==='notifications'" @click="toggle('notifications')"><UiIcon name="bell" size="1.55rem"/><span v-if="unreadNotifications.length" class="notification-badge">{{unreadNotifications.length>99?'99+':unreadNotifications.length}}</span></button><button class="icon-button" :aria-label="full?'退出全屏':'进入全屏'" :title="fullSupported?(full?'退出全屏':'进入全屏'):'当前浏览器不支持网页全屏'" :aria-pressed="full" @click="toggleFull"><UiIcon :name="full?'fullscreenExit':'fullscreen'" size="1.45rem"/></button><button class="icon-button font-button" aria-label="字号与显示设置" :aria-expanded="panel==='font'" @click="toggle('font')"><UiIcon name="font" size="1.65rem"/></button></div>
 <button class="profile-button" :aria-expanded="panel==='account'" aria-label="管理员账号菜单" @click="toggle('account')"><UiIcon name="chevron" size="1rem"/><span>{{account.user.displayName}}</span><span class="avatar">{{avatar}}</span></button>
 <section v-if="panel==='account'" class="account-dropdown toolbar-popup"><div class="account-dropdown-head"><strong>{{account.user.displayName}}</strong><small>{{account.user.username}} · 管理员</small></div><button @click="accountAction('profile')">个人中心</button><button v-if="!isStaticDemo" @click="accountAction('password')">修改密码</button><button @click="accountAction('preferences')">显示设置</button><button @click="close();emit('runtime')">运行状态与说明</button><button class="logout-action" :disabled="saving" @click="logout">{{saving?'正在退出…':isStaticDemo?'退出演示':'退出登录'}}</button></section>
 <section v-if="panel==='font'" class="font-popover toolbar-popup"><h3>全局字号</h3><button v-for="item in [{id:'normal',label:'标准字号'},{id:'large',label:'较大字号'},{id:'xlarge',label:'大字号'}]" :key="item.id" :class="{selected:account.user.preferences.fontSize===item.id}" :disabled="saving" @click="chooseFont(item.id)"><span>{{item.label}}</span><span v-if="account.user.preferences.fontSize===item.id">✓</span></button><button class="display-settings-link" @click="accountAction('preferences')">更多显示设置 →</button></section>
 <section v-if="panel==='search'" class="global-search-panel toolbar-popup" aria-label="全局搜索面板"><div class="global-search-input"><UiIcon name="search"/><input ref="searchInput" v-model="query" aria-label="全局搜索关键词" placeholder="菜单、站点、设备、插座、订单或报修" @input="activeResult=-1" @keydown.down.prevent="moveResult(1)" @keydown.up.prevent="moveResult(-1)" @keydown.enter.prevent="enterResult"/><button class="icon-button" aria-label="关闭搜索" @click="close"><UiIcon name="close"/></button></div><div class="global-search-results"><template v-for="(item,i) in searchResults" :key="item.key"><h4 v-if="i===0||searchResults[i-1].kind!==item.kind">{{kinds[item.kind]}}</h4><button :class="{'keyboard-active':activeResult===i}" @mouseenter="activeResult=i" @click="selectResult(item)"><span class="search-type">{{kinds[item.kind]}}</span><span class="search-result-copy"><strong>{{item.title}}</strong><small>{{item.description}}</small></span><UiIcon name="arrow" size="1rem"/></button></template><p v-if="!searchResults.length" class="search-empty">没有找到匹配结果，请尝试编号或其他关键词。</p></div><footer>↑ ↓ 选择 · Enter 打开 · Esc 关闭 <span>每类最多显示 8 条</span></footer></section>
 <section v-if="panel==='notifications'" class="notification-panel toolbar-popup" aria-label="通知中心面板"><header><div><h3>通知中心 <small>{{unreadNotifications.length}} 条未读</small></h3><p>{{isStaticDemo?'演示通知与已读状态仅保存在当前浏览器':'本地模拟业务通知，已读状态按账号保存'}}</p></div><button class="text-button" :disabled="!unreadNotifications.length||noticeBusy" @click="readAll">全部已读</button></header><div class="notification-filters"><button :class="{active:noticeFilter==='all'}" @click="noticeFilter='all';noticeLimit=20">全部</button><button :class="{active:noticeFilter==='unread'}" @click="noticeFilter='unread';noticeLimit=20">未读</button><button class="text-button" @click="refreshReadState">刷新</button></div><p v-if="noticeError" class="notification-error" role="alert">{{noticeError}}</p><div class="notification-items"><button v-for="item in visibleNotices" :key="item.key" :class="{unread:!readKeys.has(item.key)}" :disabled="noticeBusy" @click="readNotice(item)"><i></i><span><strong>{{item.title}}</strong><small>{{item.description}}</small><time>{{displayTime(item.createdAt)}} · {{readKeys.has(item.key)?'已读':'未读'}}</time></span><UiIcon name="arrow" size="1rem"/></button><p v-if="!visibleNotices.length" class="search-empty">{{noticeFilter==='unread'?'暂时没有未读通知':'暂无通知'}}</p></div><footer v-if="noticeLimit<noticeTotal"><button class="text-button" @click="noticeLimit+=20">加载更多（已显示 {{visibleNotices.length}} / {{noticeTotal}}）</button></footer></section>
</div></template>
